{
  "primary_meaning": "God's gentle blessing, favor, or spiritual refreshment/revival poured out quietly upon His people",
  "primary_basis": [
    "Hosea 14:5 (I will be like the dew to Israel)",
    "Deuteronomy 33:13/28 (blessing of heaven's dew)",
    "Psalm 133:3 (dew of Hermon as emblem of blessing/unity)",
    "Micah 5:7 (remnant like dew from the Lord)",
    "Zechariah 8:12 (heavens give dew as covenant blessing)"
  ],
  "alternatives": [
    {
      "meaning": "The Word of God or true doctrine that gently nourishes",
      "basis": [
        "Deuteronomy 32:2 (doctrine drops as rain, speech distills as dew)"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Resurrection life or awakening of the dead",
      "basis": [
        "Isaiah 26:19 (your dead shall live... for your dew is like the dew of herbs)"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "Sign of divine confirmation or miraculous provision (as with Gideon's fleece or manna context)",
      "basis": [
        "Judges 6:36-40",
        "Exodus 16:13-14 (manna appearing with dew)"
      ],
      "prominence": "common"
    },
    {
      "meaning": "The Holy Spirit's quiet, life-giving influence",
      "basis": [
        "Analogical extension from Hosea 14:5 and refreshment imagery"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Across patristic, medieval, Reformation, and modern evangelical/conservative commentaries the dominant cluster is blessing/refreshment/favor; secondary readings (Word, resurrection, Spirit) are well-attested but less universal as the primary symbol. No major tradition treats dew as inherently negative."
}
